    /// The constraint for a codepoint, or nil if it isn't a Nerd Font glyph
    /// with special handling.
    static func constraint(for cp: UInt32) -> GlyphConstraint? {
        // Fast reject: ASCII and Latin never reach the binary search.
        if cp < 0x23FB || cp > 0xF1AF0 { return nil }

        var lo = 0
        var hi = ranges.count / 2 - 1
        while lo <= hi {
            let mid = (lo + hi) / 2
            if cp < ranges[mid * 2] {
                hi = mid - 1
            } else if cp > ranges[mid * 2 + 1] {
                lo = mid + 1
            } else {
                return decode(mid)
            }
        }
        return nil
    }

    private static func decode(_ i: Int) -> GlyphConstraint {
        let f = i * 6
        let v = i * 9
        return GlyphConstraint(
            size: GlyphConstraint.Size(rawValue: flags[f]) ?? .none,
            alignVertical: GlyphConstraint.Align(rawValue: flags[f + 1]) ?? .none,
            alignHorizontal: GlyphConstraint.Align(rawValue: flags[f + 2]) ?? .none,
            padTop: values[v],
            padLeft: values[v + 1],
            padRight: values[v + 2],
            padBottom: values[v + 3],
            relativeWidth: values[v + 4],
            relativeHeight: values[v + 5],
            relativeX: values[v + 6],
            relativeY: values[v + 7],
            maxXYRatio: flags[f + 5] != 0 ? values[v + 8] : nil,
            maxConstraintWidth: flags[f + 4],
            height: GlyphConstraint.Height(rawValue: flags[f + 3]) ?? .cell)
    }
